1	import { useEffect, useRef, useState } from 'react';
2	import { Cta, OnboardIllustration, Screen, Sub, Title } from '../chrome';
3	
4	/* ── profile ─────────────────────────────────────────────────────────── */
5	
6	const MIN_AGE = 13;
7	const MAX_AGE = 99;
8	/** px between year ticks on the ruler */
9	const TICK = 14;
10	
11	export function Profile({
12	  age,
13	  gender,
14	  onChange,
15	  onNext,
16	}: {
17	  age: number | null;
18	  gender: 'm' | 'f' | 'na' | null;
19	  onChange: (p: { age?: number; gender: 'm' | 'f' | 'na' | null }) => void;
20	  onNext: () => void;
21	}) {
22	  const value = age ?? 25;
23	  const set = (n: number) => onChange({ age: Math.round(Math.min(MAX_AGE, Math.max(MIN_AGE, n))), gender });
24	
25	  const drag = useRef<{ x: number; start: number } | null>(null);
26	  const [width, setWidth] = useState(320);
27	  const railRef = useRef<HTMLDivElement>(null);
28	
29	  useEffect(() => {
30	    const measure = () => railRef.current && setWidth(railRef.current.clientWidth);
31	    measure();
32	    window.addEventListener('resize', measure);
33	    return () => window.removeEventListener('resize', measure);
34	  }, []);
35	
36	  const onDown = (e: React.PointerEvent) => {
37	    drag.current = { x: e.clientX, start: value };
38	    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
39	  };
40	  const onMove = (e: React.PointerEvent) => {
41	    if (!drag.current) return;
42	    set(drag.current.start - (e.clientX - drag.current.x) / TICK);
43	  };
44	  const onUp = () => {
45	    drag.current = null;
46	  };
47	
48	  // enough ticks either side to fill the rail, clipped to the real range
49	  const half = Math.ceil(width / TICK / 2) + 1;
50	  const ticks: number[] = [];
51	  for (let y = value - half; y <= value + half; y++) if (y >= MIN_AGE && y <= MAX_AGE) ticks.push(y);
52	
53	  return (
54	    <Screen scroll footer={<Cta onClick={onNext}>Continue</Cta>}>
55	      <Title>About you</Title>
56	      <Sub>Dose ranges differ by age and sex. This stays on your device.</Sub>
57	
58	      <div className="ob-age">
59	        <div className="ob-age-num">
60	          {value}
61	          <span className="ob-age-unit">yrs</span>
62	        </div>
63	
64	        <div
65	          className="ob-ruler"
66	          ref={railRef}
67	          onPointerDown={onDown}
68	          onPointerMove={onMove}
69	          onPointerUp={onUp}
70	          onPointerCancel={onUp}
71	          role="slider"
72	          tabIndex={0}
73	          aria-label="Age"
74	          aria-valuemin={MIN_AGE}
75	          aria-valuemax={MAX_AGE}
76	          aria-valuenow={value}
77	          onKeyDown={(e) => {
78	            if (e.key === 'ArrowLeft') set(value - 1);
79	            if (e.key === 'ArrowRight') set(value + 1);
80	          }}
81	        >
82	          {ticks.map((y) => {
83	            const major = y % 5 === 0;
84	            return (
85	              <span key={y}>
86	                <span
87	                  className={`ob-ruler-mark${major ? ' major' : ''}`}
88	                  style={{ left: width / 2 + (y - value) * TICK, height: major ? 22 : 13 }}
89	                />
90	                {major && (
91	                  <span className="ob-ruler-label" style={{ left: width / 2 + (y - value) * TICK }}>
92	                    {y}
93	                  </span>
94	                )}
95	              </span>
96	            );
97	          })}
98	          <span className="ob-ruler-needle" />
99	        </div>
100	
101	        <div className="ob-age-steppers">
102	          <button className="ob-stepper" onClick={() => set(value - 1)} aria-label="One year younger">
103	            <svg width="16" height="16" viewBox="0 0 16 16" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" aria-hidden>
104	              <path d="M3.5 8h9" />
105	            </svg>
106	          </button>
107	          <button className="ob-stepper" onClick={() => set(value + 1)} aria-label="One year older">
108	            <svg width="16" height="16" viewBox="0 0 16 16" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" aria-hidden>
109	              <path d="M8 3.5v9M3.5 8h9" />
110	            </svg>
111	          </button>
112	        </div>
113	      </div>
114	
115	      <div className="ob-pill-row" style={{ marginTop: 30 }}>
116	        {([['m', 'Male'], ['f', 'Female'], ['na', 'Prefer not to say']] as const).map(([id, label]) => (
117	          <button
118	            key={id}
119	            className={`ob-pill${gender === id ? ' on' : ''}`}
120	            aria-pressed={gender === id}
121	            onClick={() => onChange({ age: value, gender: id })}
122	          >
123	            {label}
124	          </button>
125	        ))}
126	      </div>
127	    </Screen>
128	  );
129	}
130	
131	/* ── the two read-only explainers ────────────────────────────────────── */
132	
133	export const INFO_COPY = {
134	  'info-library': {
135	    illustration: 'library',
136	    title: 'Where this comes from',
137	    body: 'Every entry is tied to published research rather than to anything we decided ourselves. You can open the papers behind any of it from Discover, at any point, without asking us.',
138	  },
139	  'info-recs': {
140	    illustration: 'recs',
141	    title: 'How a suggestion is made',
142	    body: 'Suggestions are drawn from the goals you pick, your age and your sex — nothing else. You set every amount yourself; the app stores your numbers and never invents them.',
143	  },
144	} as const;
145	
146	export function Info({ which, onNext }: { which: keyof typeof INFO_COPY; onNext: () => void }) {
147	  const c = INFO_COPY[which];
148	  return (
149	    <Screen center footer={<Cta onClick={onNext}>Continue</Cta>}>
150	      <OnboardIllustration name={c.illustration} />
151	      <div style={{ marginTop: 30 }}>
152	        <Title>{c.title}</Title>
153	        <Sub>{c.body}</Sub>
154	      </div>
155	    </Screen>
156	  );
157	}
158	
159	/* ── the three survey questions ──────────────────────────────────────── */
160	
161	export interface Question {
162	  id: 'q1' | 'q2' | 'q3';
163	  title: string;
164	  sub: string;
165	  options: { id: string; label: string }[];
166	}
167	
168	/**
169	 * Every one of these changes something downstream. None of them exists to make
170	 * the user feel bad about themselves — that shape of question produces refunds
171	 * a week later, not engagement.
172	 */
173	export const QUESTIONS: Record<'q1' | 'q2' | 'q3', Question> = {
174	  q1: {
175	    id: 'q1',
176	    title: 'How many peptides or supplements are you taking right now?',
177	    sub: 'Count each one separately, including anything over the counter.',
178	    options: [
179	      { id: 'none', label: 'None yet' },
180	      { id: '1-2', label: '1–2' },
181	      { id: '3-5', label: '3–5' },
182	      { id: '6+', label: '6 or more' },
183	    ],
184	  },
185	  q2: {
186	    id: 'q2',
187	    title: 'Have you started a routine and stopped before?',
188	    sub: 'There is no wrong answer here.',
189	    options: [
190	      { id: 'never', label: 'Never tried' },
191	      { id: 'once', label: 'Once or twice' },
192	      { id: 'several', label: 'Several times' },
193	      { id: 'always', label: 'I always stop' },
194	    ],
195	  },
196	  q3: {
197	    id: 'q3',
198	    title: 'What usually goes wrong?',
199	    sub: 'This decides how the schedule is laid out.',
200	    options: [
201	      { id: 'forget', label: 'I forget' },
202	      { id: 'too-many', label: 'Too many to keep track of' },
203	      { id: 'unsure', label: 'Not sure it’s working' },
204	      { id: 'nothing', label: 'Nothing, I’m consistent' },
205	    ],
206	  },
207	};
208	
209	export function SurveyScreen({
210	  question,
211	  value,
212	  onPick,
213	  onNext,
214	}: {
215	  question: Question;
216	  value: string | null;
217	  onPick: (v: string) => void;
218	  onNext: () => void;
219	}) {
220	  return (
221	    <Screen
222	      scroll
223	      footer={
224	        <Cta onClick={onNext} disabled={value === null}>
225	          Continue
226	        </Cta>
227	      }
228	    >
229	      <Title>{question.title}</Title>
230	      <Sub>{question.sub}</Sub>
231	
232	      <div className="ob-options" role="radiogroup" aria-label={question.title}>
233	        {question.options.map((o) => (
234	          <button
235	            key={o.id}
236	            role="radio"
237	            aria-checked={value === o.id}
238	            className={`ob-option${value === o.id ? ' on' : ''}`}
239	            onClick={() => onPick(o.id)}
240	          >
241	            {o.label}
242	            <span className={`ob-tick${value === o.id ? ' on' : ''}`}>
243	              {value === o.id && (
244	                <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="var(--bg)" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
245	                  <path d="M2.5 6.2 4.8 8.5 9.5 3.5" />
246	                </svg>
247	              )}
248	            </span>
249	          </button>
250	        ))}
251	      </div>
252	    </Screen>
253	  );
254	}
