1	import type { ReactNode } from 'react';
2	import { FLOW, NO_BACK, SKIPPABLE, type Step } from './flow';
3	
4	export function Wordmark({ size = 17 }: { size?: number }) {
5	  return (
6	    <span className="ob-wordmark" style={{ fontSize: size }}>
7	      <LogoMark size={Math.round(size * 1.15)} />
8	      Pepstack
9	    </span>
10	  );
11	}
12	
13	/** A capsule on its side, split — the stack, and the schedule cutting it up. */
14	export function LogoMark({ size = 20, color = 'var(--accent)' }: { size?: number; color?: string }) {
15	  return (
16	    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden>
17	      <rect x="2.6" y="7.4" width="18.8" height="9.2" rx="4.6" stroke={color} strokeWidth="1.9" />
18	      <path d="M12 7.4v9.2" stroke={color} strokeWidth="1.9" strokeLinecap="round" />
19	    </svg>
20	  );
21	}
22	
23	/**
24	 * One segment per step. Filled segments are the steps behind you, so it can
25	 * never claim "87% complete" on step four — the denominator is the real flow
26	 * length and every segment is the same width.
27	 */
28	export function ProgressBar({ step }: { step: Step }) {
29	  const index = FLOW.indexOf(step);
30	  return (
31	    <div
32	      className="ob-progress"
33	      role="progressbar"
34	      aria-valuemin={1}
35	      aria-valuemax={FLOW.length}
36	      aria-valuenow={index + 1}
37	      aria-label={`Step ${index + 1} of ${FLOW.length}`}
38	    >
39	      {FLOW.map((s, i) => (
40	        <span key={s} className={`ob-seg${i <= index ? ' on' : ''}`} />
41	      ))}
42	    </div>
43	  );
44	}
45	
46	export function Header({
47	  step,
48	  onBack,
49	  onSkip,
50	}: {
51	  step: Step;
52	  onBack: () => void;
53	  onSkip: () => void;
54	}) {
55	  const canBack = !NO_BACK.has(step) && FLOW.indexOf(step) > 0;
56	  return (
57	    <header className="ob-header">
58	      <div className="ob-header-row">
59	        {canBack ? (
60	          <button className="ob-back" onClick={onBack} aria-label="Back">
61	            <svg width="22" height="22" viewBox="0 0 22 22" fill="none" aria-hidden>
62	              <path
63	                d="M13.5 4.5 7 11l6.5 6.5"
64	                stroke="currentColor"
65	                strokeWidth="1.9"
66	                strokeLinecap="round"
67	                strokeLinejoin="round"
68	              />
69	            </svg>
70	          </button>
71	        ) : (
72	          <span className="ob-header-spacer" />
73	        )}
74	
75	        <Wordmark />
76	
77	        {SKIPPABLE.has(step) ? (
78	          <button className="ob-skip" onClick={onSkip}>
79	            Skip
80	          </button>
81	        ) : (
82	          <span className="ob-header-spacer" />
83	        )}
84	      </div>
85	      <ProgressBar step={step} />
86	    </header>
87	  );
88	}
