16	/* ── sleep ───────────────────────────────────────────────────────────── */
17	
18	const DIAL = 236;
19	const DIAL_R = 94;
20	const DIAL_STROKE = 18;
21	const HANDLE_R = 13;
22	/** minutes the handles snap to */
23	const SNAP = 5;
24	
25	const angleOf = (t: string) => (toMin(t) / 1440) * 360;
26	const onRing = (deg: number, r = DIAL_R) => {
27	  const rad = ((deg - 90) * Math.PI) / 180;
28	  return [DIAL / 2 + r * Math.cos(rad), DIAL / 2 + r * Math.sin(rad)] as const;
29	};
30	const timeOf = (deg: number) => {
31	  const mins = Math.round((((deg % 360) + 360) % 360 / 360) * 1440 / SNAP) * SNAP;
32	  const m = mins % 1440;
33	  return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`;
34	};
35	
36	export function Sleep({
37	  wake,
38	  sleep,
39	  onChange,
40	  onNext,
41	}: {
42	  wake: string;
43	  sleep: string;
44	  onChange: (p: { wake: string; sleep: string }) => void;
45	  onNext: () => void;
46	}) {
47	  const svgRef = useRef<SVGSVGElement>(null);
48	  const dragging = useRef<'wake' | 'sleep' | null>(null);
49	
50	  // hours in bed, wrapping past midnight
51	  const mins = (toMin(wake) - toMin(sleep) + 1440) % 1440;
52	  const hours = Math.floor(mins / 60);
53	  const rest = mins % 60;
54	
55	  const c = DIAL / 2;
56	  const circumference = 2 * Math.PI * DIAL_R;
57	  const startDeg = angleOf(sleep);
58	  const [wx, wy] = onRing(angleOf(wake));
59	  const [sx, sy] = onRing(startDeg);
60	
61	  /** Angle is invariant to how the SVG is scaled, so the centre is enough. */
62	  const degFromPointer = (e: { clientX: number; clientY: number }) => {
63	    const box = svgRef.current!.getBoundingClientRect();
64	    const dx = e.clientX - (box.left + box.width / 2);
65	    const dy = e.clientY - (box.top + box.height / 2);
66	    return (Math.atan2(dx, -dy) * 180) / Math.PI;
67	  };
68	
69	  const move = (e: React.PointerEvent) => {
70	    const which = dragging.current;
71	    if (!which) return;
72	    const t = timeOf(degFromPointer(e));
73	    onChange(which === 'wake' ? { wake: t, sleep } : { wake, sleep: t });
74	  };
75	
76	  const grab = (which: 'wake' | 'sleep') => (e: React.PointerEvent) => {
77	    e.preventDefault();
78	    dragging.current = which;
79	    (e.currentTarget as SVGElement).setPointerCapture?.(e.pointerId);
80	  };
81	  const release = () => {
82	    dragging.current = null;
83	  };
84	
85	  const nudge = (which: 'wake' | 'sleep', delta: number) => {
86	    const cur = which === 'wake' ? wake : sleep;
87	    const t = timeOf(((toMin(cur) + delta + 1440) % 1440 / 1440) * 360);
88	    onChange(which === 'wake' ? { wake: t, sleep } : { wake, sleep: t });
89	  };
90	
91	  return (
92	    <Screen scroll footer={<Cta onClick={onNext}>Continue</Cta>}>
93	      <Title>Your day, part one</Title>
94	      <Sub>Drag either end of the ring. We schedule around the window, not the minute.</Sub>
95	
96	      <div className="ob-dial-wrap">
97	        <svg
98	          ref={svgRef}
99	          className="ob-dial"
100	          width={DIAL}
101	          height={DIAL}
102	          viewBox={`0 0 ${DIAL} ${DIAL}`}
103	          onPointerMove={move}
104	          onPointerUp={release}
105	          onPointerCancel={release}
106	        >
107	          <circle cx={c} cy={c} r={DIAL_R} fill="none" stroke="var(--card)" strokeWidth={DIAL_STROKE} />
108	          <circle
109	            cx={c}
110	            cy={c}
111	            r={DIAL_R}
112	            fill="none"
113	            stroke="var(--accent)"
114	            strokeWidth={DIAL_STROKE}
115	            strokeLinecap="round"
116	            strokeDasharray={`${circumference * (mins / 1440)} ${circumference}`}
117	            transform={`rotate(${startDeg - 90} ${c} ${c})`}
118	          />
119	
120	          {/* twelve ticks, so the ring reads as a clock rather than a gauge */}
121	          {Array.from({ length: 12 }, (_, i) => {
122	            const [x1, y1] = onRing(i * 30, DIAL_R - DIAL_STROKE / 2 - 7);
123	            const [x2, y2] = onRing(i * 30, DIAL_R - DIAL_STROKE / 2 - (i % 3 === 0 ? 13 : 10));
124	            return <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="var(--t4)" strokeWidth="2" strokeLinecap="round" />;
125	          })}
126	
127	          <Handle
128	            x={sx}
129	            y={sy}
130	            label="Go to sleep"
131	            value={sleep}
132	            onGrab={grab('sleep')}
133	            onNudge={(d) => nudge('sleep', d)}
134	          />
135	          <Handle
136	            x={wx}
137	            y={wy}
138	            label="Wake up"
139	            value={wake}
140	            onGrab={grab('wake')}
141	            onNudge={(d) => nudge('wake', d)}
142	          />
143	        </svg>
144	
145	        <div className="ob-dial-centre">
146	          <div className="ob-dial-hours">
147	            {hours}h{rest ? ` ${rest}m` : ''}
148	          </div>
149	          <div className="ob-dial-label">In bed</div>
150	        </div>
151	      </div>
152	
153	      <div className="ob-time-row">
154	        <div className="ob-time-card">
155	          <label htmlFor="ob-sleep">Go to sleep</label>
156	          <input
157	            id="ob-sleep"
158	            type="time"
159	            value={sleep}
160	            onChange={(e) => onChange({ wake, sleep: e.target.value || '23:00' })}
161	          />
162	        </div>
163	        <div className="ob-time-card">
164	          <label htmlFor="ob-wake">Wake up</label>
165	          <input
166	            id="ob-wake"
167	            type="time"
168	            value={wake}
169	            onChange={(e) => onChange({ wake: e.target.value || '07:00', sleep })}
170	          />
171	        </div>
172	      </div>
173	    </Screen>
174	  );
175	}
176	
177	/** A grab point on the ring. The visible dot is 13px; the target is 22. */
178	function Handle({
179	  x,
180	  y,
181	  label,
182	  value,
183	  onGrab,
184	  onNudge,
185	}: {
186	  x: number;
187	  y: number;
188	  label: string;
189	  value: string;
190	  onGrab: (e: React.PointerEvent) => void;
191	  onNudge: (deltaMinutes: number) => void;
192	}) {
193	  return (
194	    <g
195	      className="ob-dial-handle"
196	      onPointerDown={onGrab}
197	      role="slider"
198	      tabIndex={0}
199	      aria-label={label}
200	      aria-valuetext={`${label} ${fmt(value)}`}
201	      aria-valuenow={toMin(value)}
202	      aria-valuemin={0}
203	      aria-valuemax={1439}
204	      onKeyDown={(e) => {
205	        if (e.key === 'ArrowLeft' || e.key === 'ArrowDown') onNudge(-15);
206	        if (e.key === 'ArrowRight' || e.key === 'ArrowUp') onNudge(15);
207	      }}
208	    >
209	      <circle cx={x} cy={y} r={22} fill="transparent" />
210	      <circle cx={x} cy={y} r={HANDLE_R} fill="var(--bg)" stroke="var(--accent)" strokeWidth="3.5" />
211	      <circle cx={x} cy={y} r={4} fill="var(--accent-light)" />
212	    </g>
213	  );
214	}
215	
216	/* ── meals ───────────────────────────────────────────────────────────── */
217	
218	export function Meals({
219	  meals,
220	  onChange,
221	  onNext,
222	}: {
223	  meals: Meal[];
224	  onChange: (m: Meal[]) => void;
225	  onNext: () => void;
226	}) {
227	  const [leaving, setLeaving] = useState<string | null>(null);
228	
229	  const remove = (id: string) => {
230	    setLeaving(id);
231	    // let the card collapse before it leaves the list
232	    setTimeout(() => {
233	      onChange(meals.filter((m) => m.id !== id));
234	      setLeaving(null);
235	    }, 200);
236	  };
237	
238	  const add = () => {
239	    const last = meals.length ? toMin(meals[meals.length - 1].time) : 8 * 60;
240	    const t = Math.min(23 * 60 + 30, last + 240);
241	    onChange([
242	      ...meals,
243	      {
244	        id: `meal-${Date.now()}`,
245	        name: 'Meal',
246	        time: `${String(Math.floor(t / 60)).padStart(2, '0')}:${String(t % 60).padStart(2, '0')}`,
247	      },
248	    ]);
249	  };
250	
251	  const patch = (id: string, p: Partial<Meal>) =>
252	    onChange(meals.map((m) => (m.id === id ? { ...m, ...p } : m)));
253	
254	  return (
255	    <Screen scroll footer={<Cta onClick={onNext}>Continue</Cta>}>
256	      <Title>Your day, part two</Title>
257	      <Sub>Anything that needs food gets scheduled near one of these.</Sub>
258	
259	      <div className="ob-meals">
260	        {[...meals]
261	          .sort((a, b) => toMin(a.time) - toMin(b.time))
262	          .map((m) => (
263	            <div key={m.id} className={`ob-meal${leaving === m.id ? ' leaving' : ''}`}>
264	              <div className="ob-meal-main">
265	                <input
266	                  className="ob-meal-name"
267	                  value={m.name}
268	                  onChange={(e) => patch(m.id, { name: e.target.value })}
269	                  aria-label="Meal name"
270	                />
271	                <input
272	                  type="time"
273	                  value={m.time}
274	                  onChange={(e) => patch(m.id, { time: e.target.value })}
275	                  aria-label={`${m.name} time`}
276	                />
277	              </div>
278	              <button className="ob-meal-del" onClick={() => remove(m.id)} aria-label={`Remove ${m.name}`}>
279	                <svg width="19" height="19" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" aria-hidden>
280	                  <path d="M3.5 5.5h13M8 5.5V4a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1v1.5M5.5 5.5 6.3 16a1 1 0 0 0 1 .9h5.4a1 1 0 0 0 1-.9l.8-10.5" />
281	                </svg>
282	              </button>
283	            </div>
284	          ))}
285	      </div>
286	
287	      {meals.length === 0 && (
288	        <p className="ob-caption" style={{ marginTop: 16 }}>
289	          No meals set — doses that would have been anchored to one get spread evenly across your day
290	          instead.
291	        </p>
292	      )}
293	
294	      <button className="ob-add" onClick={add}>
295	        <svg width="15" height="15" viewBox="0 0 16 16" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" fill="none" aria-hidden>
296	          <path d="M8 3.5v9M3.5 8h9" />
297	        </svg>
298	        Add meal
299	      </button>
300	    </Screen>
301	  );
302	}
303	
304	/* ── current stack ───────────────────────────────────────────────────── */
305	
306	export function CurrentStack({
307	  picked,
308	  onChange,
309	  onNext,
310	}: {
311	  picked: string[];
312	  onChange: (v: string[]) => void;
313	  onNext: () => void;
314	}) {
315	  const [q, setQ] = useState('');
316	  const [all, setAll] = useState<GlossaryEntry[]>([]);
317	
318	  useEffect(() => {
319	    listGlossary(200)
320	      .then(setAll)
321	      .catch(() => setAll([]));
322	  }, []);
323	
324	  const results = q.trim()
325	    ? all.filter((e) => e.name.toLowerCase().includes(q.trim().toLowerCase()) && !picked.includes(e.name)).slice(0, 8)
326	    : [];
327	
328	  const add = (name: string) => {
329	    onChange([...picked, name]);
330	    setQ('');
331	  };
332	
333	  return (
334	    <Screen
335	      scroll
336	      footer={
337	        <>
338	          <Cta onClick={onNext}>Continue</Cta>
339	          {picked.length === 0 && (
340	            <button className="ob-textlink" onClick={onNext} style={{ marginTop: 10 }}>
341	              Nothing yet
342	            </button>
343	          )}
344	        </>
345	      }
346	    >
347	      <Title>What are you already taking?</Title>
348	      {/* This is what makes the double-up check possible at all. */}
349	      <Sub>So we can spot anything you would end up taking twice.</Sub>
350	
351	      <input
352	        className="ob-input"
353	        style={{ marginTop: 22 }}
354	        value={q}
355	        onChange={(e) => setQ(e.target.value)}
356	        placeholder="Search by name"
357	        aria-label="Search supplements"
358	      />
359	
360	      {results.length > 0 && (
361	        <div className="ob-results">
362	          {results.map((r) => (
363	            <button key={r.id} className="ob-result" onClick={() => add(r.name)}>
364	              {r.name}
365	              <span className="ob-caption">{r.category}</span>
366	            </button>
367	          ))}
368	        </div>
369	      )}
370	
371	      {q.trim() && results.length === 0 && (
372	        <button className="ob-result" style={{ marginTop: 14 }} onClick={() => add(q.trim())}>
373	          Add “{q.trim()}”
374	          <span className="ob-caption">not in our list</span>
375	        </button>
376	      )}
377	
378	      {picked.length > 0 && (
379	        <div className="ob-chips">
380	          {picked.map((name) => (
381	            <span className="ob-chip" key={name}>
382	              {name}
383	              <button onClick={() => onChange(picked.filter((p) => p !== name))} aria-label={`Remove ${name}`}>
384	                <svg width="12" height="12" viewBox="0 0 12 12" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden>
385	                  <path d="M3 3l6 6M9 3l-6 6" />
386	                </svg>
387	              </button>
388	            </span>
389	          ))}
390	        </div>
391	      )}
392	    </Screen>
393	  );
394	}
395	
396	export { fmt as formatClock, toMin as clockToMinutes };
397	
398	/** Keeps the meal-name input from being restyled by the generic input rules. */
399	export function useNoop() {
400	  const r = useRef(null);
401	  return r;
402	}
403

