const toMin = (t: string) => {
  const [h, m] = t.split(':').map(Number);
  return h * 60 + (m || 0);
};
const fmt = (t: string) => {
  const [h, m] = t.split(':').map(Number);
  const period = h >= 12 ? 'PM' : 'AM';
  return `${h % 12 === 0 ? 12 : h % 12}:${String(m).padStart(2, '0')} ${period}`;
};

/* ── sleep ───────────────────────────────────────────────────────────── */

const DIAL = 236;
const DIAL_R = 94;
const DIAL_STROKE = 18;
const HANDLE_R = 13;
